#!/usr/bin/env python3
"""Generate spike-parity Steam/FMOD stub .c files from monodis --implmap dumps.

Inputs (in this directory):
  celeste.implmap     — `monodis --implmap` of Celeste.exe (489 entries:
                        320 fmod + 169 fmodstudio)
  steamworks.implmap  — `monodis --implmap` of Steamworks.NET.dll (872 entries:
                        864 CSteamworks + 8 sdkencryptedappticket)
  overrides-fmod.txt / overrides-steam.txt — native names with hand-written
                        implementations in fmod_overrides.c / steam_overrides.c

Outputs: gen/gen_fmod.c, gen/gen_steam.c.

Every P/Invoke the game declares gets a symbol, so Mono's lazy binder never
throws EntryPointNotFoundException for an uncalled function. Default returns
are plausible-but-dumb (FMOD_RESULT 0 = OK, bool true, fake non-NULL
pointers, numeric 0); functions whose out-params or values gate boot
progress are overridden by hand instead. See README.md.

A generated stub is declared f(void) and ignores its arguments: on SysV
x86-64 the caller cleans the stack and the return value travels in
RAX/XMM0, so a zero-arg callee is ABI-compatible with any caller. The only
exceptions are struct-by-value returns (the three Steam Controller data
functions), which are hand-written in steam_overrides.c with the correct
SysV struct-return ABI.
"""
import re
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent

IMPLMAP_RE = re.compile(
    r"^\d+: (.*?) (?:class |valuetype )?[\w\.]+::\w+\(.*\) \d+ \((\S+) (\S+)\)$"
)

# managed return type -> (C return type, return expression)
RET_MAP = {
    "valuetype FMOD.RESULT": ("int", "0"),          # FMOD_OK
    "bool": ("int", "1"),                           # bool marshals as 1 byte; AL=1 -> true
    "void": ("void", None),
    "native int": ("void *", "stub_dummy"),         # fake non-NULL pointer (zeroed buffer)
    "int32": ("int", "0"),
    "unsigned int32": ("unsigned int", "0"),
    "int64": ("long long", "0"),
    "unsigned int64": ("unsigned long long", "0"),
    "int16": ("int", "0"),
    "unsigned int8": ("int", "0"),
    "float32": ("float", "0.0f"),
    "float64": ("double", "0.0"),
}
STRUCT_RET_RE = re.compile(r"^valuetype Steamworks\.\w+_t$")  # Steam *_t types are structs
ENUM_RE = re.compile(r"^valuetype Steamworks\.\w+$")          # any other Steam valuetype is an enum (int-sized)

HEADER = """// GENERATED by gen-stubs.py from {src} — do not edit by hand.
// Spike-parity stubs: every P/Invoke the game declares gets a symbol so
// Mono's lazy binder never throws EntryPointNotFoundException. Default
// returns are plausible-but-dumb; boot-critical functions are overridden
// by hand in {overrides} instead (see overrides-{tag}.txt).
// A stub declared f(void) ignores its arguments: on SysV x86-64 the caller
// cleans the stack and the return travels in RAX/XMM0, so a zero-arg callee
// is ABI-compatible with any caller.
#include <stddef.h>

static unsigned char stub_dummy[256] __attribute__((unused));

"""


def parse_implmap(path):
    """Return {native_name: (rettype, module, managed_sig)}."""
    entries = {}
    for line in Path(path).read_text().splitlines():
        m = IMPLMAP_RE.match(line.strip())
        if not m:
            continue
        rettype, name, module = m.group(1), m.group(2), m.group(3)
        if name in entries:
            prev = entries[name]
            if prev[0] != rettype:
                raise SystemExit(
                    f"CONFLICT: {name} has return types {prev[0]!r} and {rettype!r}"
                )
            continue
        entries[name] = (rettype, module, line.strip())
    return entries


def c_return(rettype):
    if rettype in RET_MAP:
        return RET_MAP[rettype]
    if STRUCT_RET_RE.match(rettype):
        return None  # hand-written (struct-by-value ABI)
    if ENUM_RE.match(rettype):
        return ("int", "0")
    raise SystemExit(f"UNKNOWN return type: {rettype!r}")


def generate(implmap, overrides_file, out_path, tag):
    entries = parse_implmap(HERE / implmap)
    overrides = {
        ln.strip()
        for ln in (HERE / overrides_file).read_text().splitlines()
        if ln.strip() and not ln.startswith("#")
    }
    # every override must name a real implmap entry (else dead code)
    for o in sorted(overrides):
        if o not in entries:
            raise SystemExit(f"OVERRIDE NOT IN IMPLMAP: {o} ({overrides_file})")
    gen = HERE / "gen"
    gen.mkdir(exist_ok=True)
    lines = [HEADER.format(src=implmap, overrides=overrides_file.replace(".txt", ".c"), tag=tag)]
    n_gen = n_skip = 0
    for name in sorted(entries):
        rettype, module, sig = entries[name]
        if name in overrides:
            n_skip += 1
            continue
        cr = c_return(rettype)
        if cr is None:
            raise SystemExit(
                f"STRUCT RETURN not overridden: {name} ({rettype}) — "
                "add it to " + overrides_file
            )
        ctype, val = cr
        lines.append(f"/* {sig} */")
        if ctype == "void":
            lines.append(f"void {name}(void) {{}}")
        else:
            lines.append(f"{ctype} {name}(void) {{ return {val}; }}")
        lines.append("")
        n_gen += 1
    (gen / out_path).write_text("\n".join(lines))
    print(f"{tag}: {len(entries)} implmap entries, {n_gen} generated, {n_skip} overridden -> gen/{out_path}")
    return len(entries)


def main():
    total = 0
    total += generate("celeste.implmap", "overrides-fmod.txt", "gen_fmod.c", "fmod")
    total += generate("steamworks.implmap", "overrides-steam.txt", "gen_steam.c", "steam")
    print(f"total implmap entries covered: {total}")


if __name__ == "__main__":
    main()
